function createUnit(def,team,x,z){return makeGod(def,team,x,z)}
const $=s=>document.querySelector(s),rand=a=>a[Math.floor(Math.random()*a.length)];
function say(text){const e=$('#message');e.textContent=text;e.classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>e.classList.remove('show'),2100)}
function draw(){ $('#gold').textContent=state.gold;$('#hp').textContent=state.hp;$('#round').textContent=state.round;$('#phase').textContent='· '+state.phase.toUpperCase();$('#teamcount').textContent=`${state.team.length} / 4`;$('#formcount').textContent=`${state.team.length} / 4`;$('#battle').disabled=state.phase==='battle';$('#battle').textContent=state.phase==='battle'?'⚔  FIGHTING…':'⚔  BEGIN BATTLE';
const shop=$('#shop');shop.innerHTML=`<div class="shophead"><b>DIVINE<br>OFFERINGS</b><small>Choose a champion</small><button class="shopbtn" id="reroll">⟳ REROLL · 2</button></div>`+state.shop.map((d,i)=>`<div class="shopcard ${state.gold<d.cost||state.bench.length>=6?'disabled':''}" data-shop="${i}"><span class="price">✦ ${d.cost}</span><div class="shopavatar" style="background:radial-gradient(circle at 50% 25%,#${d.color.toString(16).padStart(6,'0')},#292d34 78%)">${d.icon}</div><div class="shopdetails"><b>${d.name}</b><small>${d.title}</small></div><span class="tier">${'★'.repeat(d.cost>3?2:1)} · ${d.domain.toUpperCase()}</span></div>`).join('');
shop.querySelectorAll('[data-shop]').forEach(card=>card.onclick=()=>buy(+card.dataset.shop));$('#reroll').onclick=()=>{if(state.phase==='battle')return;if(state.gold<2){say('Not enough Aether');return}state.gold-=2;newShop();draw();say('The Fates have reshuffled your offerings')};
const bench=$('#bench');bench.innerHTML='';for(let i=0;i<6;i++){let b=document.createElement('div');b.className='benchslot'+(state.bench[i]?' unit':'');b.innerHTML=state.bench[i]?`${state.bench[i].def.icon}<span class="tinyname">${state.bench[i].def.name}</span>`:'✧';if(state.bench[i]){b.onclick=()=>{state.selected={kind:'bench',index:i};document.querySelectorAll('.benchslot').forEach(e=>e.style.outline='');b.style.outline='2px solid #f1d082';say(`Selected ${state.bench[i].def.name} · choose a glowing tile`)}}bench.appendChild(b)}
const counts={War:0,Sky:0,Sea:0};state.team.forEach(u=>counts[u.def.domain]++);const sy=$('#synergies');sy.innerHTML=Object.entries(counts).map(([name,n])=>`<div class="synergy ${n?'active':'dim'}"><div class="synhead"><span class="synicon">${{War:'⚔',Sky:'☼',Sea:'♆'}[name]}</span><span class="syntext">${name}bound<small>${n>=2?'Domain blessing active!':`${n} / 2 · summon one more`}</small></span><span class="syncount">${n}/2</span></div><div class="pips"><i class="${n?'on':''}"></i><i class="${n>=2?'on':''}"></i></div></div>`).join('');
$('#formation').innerHTML=Array.from({length:8},(_,i)=>`<div class="${i<state.team.length?'filled':''}">${i<state.team.length?state.team[i].def.icon:'✧'}</div>`).join('');
const enemyDefs=state.enemy.map(u=>u.def);$('#enemyroster').innerHTML=(enemyDefs.length?enemyDefs.map(d=>`<div class="rostercard"><div class="avatar" style="background:linear-gradient(145deg,#${d.color.toString(16).padStart(6,'0')},#292831)">${d.icon}</div><div class="rostername">${d.name}<small>${d.title}</small></div></div>`):'<div class="objective" style="margin-top:12px">Titans gather beyond the veil…</div>').join('');
}
function newShop(){state.shop=Array.from({length:5},()=>rand(gods))}
function buy(i){if(state.phase==='battle')return;const d=state.shop[i];if(!d)return;if(state.gold<d.cost){say('You need more Aether');return}if(state.bench.length>=6){say('Your reserve is full');return}state.gold-=d.cost;state.bench.push({def:d});state.shop[i]=rand(gods);draw();say(`${d.name} answers your call`)}
function clearSide(team){for(const u of [...unitMeshes])if(u.userData.team===team){boardGroup.remove(u);unitMeshes.splice(unitMeshes.indexOf(u),1)}if(team==='ally')state.team=[];else state.enemy=[]}
function initEnemies(){clearSide('enemy');const count=Math.min(3+Math.floor((state.round-1)*.65),7);for(let i=0;i<count;i++){const candidates=state.round>2?gods:gods.filter(d=>d.cost<=3);let d=rand(candidates);const x=(i%4)+2,z=Math.floor(i/4);const u=createUnit(d,'enemy',x,z);u.userData.hp=Math.round(d.hp*(1+(state.round-1)*.16));u.userData.maxHp=u.userData.hp;u.userData.body.scale.setScalar(1+Math.min(.2,(state.round-1)*.025));state.enemy.push(u)}}
function boardClick(event){if(state.phase==='battle')return;const rect=canvas.getBoundingClientRect(),mouse=new THREE.Vector2((event.clientX-rect.left)/rect.width*2-1,-((event.clientY-rect.top)/rect.height)*2+1),ray=new THREE.Raycaster();ray.setFromCamera(mouse,camera);const hits=ray.intersectObjects(tileMeshes,false);if(!hits.length)return;const {x,z}=hits[0].object.userData;if(z<3){say('Your gods must stand on the forward half');return}const occupant=state.team.find(u=>u.userData.x===x&&u.userData.z===z);if(state.selected?.kind==='bench'){if(occupant){say('That tile is occupied');return}if(state.team.length>=4){say('Your formation is full');return}const benchUnit=state.bench[state.selected.index];if(!benchUnit)return;const u=createUnit(benchUnit.def,'ally',x,z);state.team.push(u);state.bench.splice(state.selected.index,1);state.selected=null;draw();return}if(occupant){say(`${occupant.userData.def.name} · ${occupant.userData.def.atk} divine damage`);return}say('Select a reserve champion, then choose a tile')}
function attackEffect(a,b){const color=a.userData.team==='ally'?0x71e6ed:0xff6763;const material=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9});const beam=new THREE.Mesh(new THREE.SphereGeometry(.11,7,6),material);beam.position.copy(a.position).add(new THREE.Vector3(0,1.3,0));scene.add(beam);projectiles.push({mesh:beam,from:beam.position.clone(),to:b.position.clone().add(new THREE.Vector3(0,1,0)),t:0,damage:a.userData.def.atk})}
function damageUnit(u,amount){u.userData.hp-=amount;const ratio=Math.max(0,u.userData.hp/u.userData.maxHp);u.userData.hpfill.scale.x=ratio;u.userData.hpfill.position.x=-(1-ratio)*.36;if(u.userData.hp<=0&&!u.userData.dead){u.userData.dead=true;u.userData.body.material=mat(0x333333);u.rotation.z=Math.PI/2;u.position.y=-.15;setTimeout(()=>{boardGroup.remove(u);unitMeshes=unitMeshes.filter(m=>m!==u)},550)}}
function endBattle(won){state.phase='prep';animating=false;if(won){state.roundWins++;state.gold+=3+Math.floor(state.round/3);state.hp=Math.min(100,state.hp+1);say('VICTORY! The gods claim +3 Aether');state.round++}else{state.hp=Math.max(0,state.hp-12);state.gold+=1;say('Defeat… the Titans claim 12 Vitality');state.round++}state.enemy=[];state.team=state.team.filter(u=>u.userData.hp>0);state.team.forEach(u=>{u.userData.hp=u.userData.maxHp;u.userData.dead=false;u.rotation.z=0;u.position.y=.1;u.userData.hpfill.scale.x=1;u.userData.hpfill.position.x=0});state.team.forEach((u,i)=>{u.userData.x=2+i%4;u.userData.z=5-Math.floor(i/4);u.position.copy(tilePos(u.userData.x,u.userData.z))});if(state.hp<=0){state.hp=100;state.round=1;state.gold=8;state.roundWins=0;clearSide('ally');state.bench=[];say('The Fates grant you another beginning')}draw()}
function startBattle(){if(state.phase==='battle')return;if(!state.team.length){say('Recruit and deploy at least one god first');return}state.selected=null;state.phase='battle';initEnemies();draw();$('#battlelabel').textContent='⚡  THE TITANS DESCEND  ⚡';$('#hint').textContent='The gods fight automatically · watch for their divine abilities';say('The battle begins!');animating=true}

