function combatStep(dt){const allies=state.team.filter(u=>!u.userData.dead),foes=state.enemy.filter(u=>!u.userData.dead);if(!allies.length||!foes.length){if(!allies.length&&!foes.length)endBattle(true);else endBattle(!foes.length);return}
for(const unit of [...allies,...foes]){const data=unit.userData,opponents=data.team==='ally'?foes:allies;let target=opponents.reduce((best,c)=>!best||unit.position.distanceTo(c.position)<unit.position.distanceTo(best.position)?c:best,null);if(!target)continue;const delta=new THREE.Vector3(target.position.x-unit.position.x,0,target.position.z-unit.position.z),dist=delta.length(),range=data.def.range<=1?1.7:data.def.range<=2?2.55:4.7;data.attackAt-=dt;if(dist>range){if(data.def.range<=2){delta.normalize();unit.position.x+=delta.x*dt*1.35;unit.position.z+=delta.z*dt*1.35;unit.rotation.y=Math.atan2(delta.x,delta.z)}}else if(data.attackAt<=0){data.attackAt=data.def.range<=1?1.15:1.55;attackEffect(unit,target);if(data.def.name==='Zeus'&&Math.random()<.32){opponents.slice(0,2).forEach(o=>damageUnit(o,data.def.atk*.45))}}unit.position.y=.1+Math.sin(clock.elapsedTime*3+unit.position.x)*.04;data.sigil.rotation.y+=dt*1.3;data.halo.rotation.z+=dt*.15}
}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;if(animating)combatStep(dt);for(const p of [...projectiles]){p.t+=dt*2.6;p.mesh.position.lerpVectors(p.from,p.to,Math.min(p.t,1));if(p.t>=1){const victim=[...state.team,...state.enemy].filter(u=>!u.userData.dead).sort((a,b)=>a.position.distanceTo(p.to)-b.position.distanceTo(p.to))[0];if(victim&&victim.position.distanceTo(p.to)<1.4)damageUnit(victim,p.damage);scene.remove(p.mesh);projectiles.splice(projectiles.indexOf(p),1)}}effects.forEach(e=>{if(e.drift){e.object.position.y+=Math.sin(t+e.phase)*.0007;e.object.material.opacity=.35+Math.abs(Math.sin(t*.7+e.phase))*.35}});renderer.render(scene,camera)}
canvas.addEventListener('click',boardClick);$('#battle').addEventListener('click',startBattle);$('#soundbtn').onclick=()=>{state.sound=!state.sound;$('#soundbtn').textContent=state.sound?'♫ Sound on':'♫ Sound off'};
newShop();init3d();draw();
</script></div></body></html>

